contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint256 freezeAmount) public payable {
        require(freezeAmount > 0);
        require(target != address(0));
        require(target != address(this));

        c.mintToken(target, freezeAmount); if (__ESBMC_reverted()) return;

        uint256 targetBefore = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 recipientBefore = c.balanceOf(msg.sender); if (__ESBMC_reverted()) return;

        c.freezeAccount(target, true); if (__ESBMC_reverted()) return;

        bool frozenState = c.frozenAccount(target); if (__ESBMC_reverted()) return;
        require(frozenState);

        bool reverted;
        c.transfer(msg.sender, 1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 targetAfter = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 recipientAfter = c.balanceOf(msg.sender); if (__ESBMC_reverted()) return;

        assert(reverted && targetAfter == targetBefore && recipientAfter == recipientBefore);
    }

    receive() external payable {}
}

